[6661] = { en = "Deeprun Rat Roundup", tier = 1,
  t = "Ratten vangen in de Deeprun",
  d = "Ahoi, jij schurk. Arrr... Arrr, zoek jij werk? We hebben hier beneden een groot rattenprobleem. En er zijn niet genoeg handen op het achterdek.$B$BWat zeg je ervan? Je hoeft alleen deze rattenvangersfluit te nemen. Speel de melodie bij het ongedierte. Ze volgen je tot het einde van de wereld!$B$BVang vijf van die kleine rotbeesten en breng ze hierheen. We hebben ze levend nodig.$B$BArrrrr...",
  o = "Vang 5 Deeprun Rats met de Rat Catcher's Flute. Breng de ratten terug naar Monty. Vergeet niet de fluit terug te geven als je klaar bent.",
  p = "Jarrr... Dekzwabber, waarom duurt het zo lang?",
  c = "Deze zijn prima, maatje. Mijn broer heeft ze levend en schoppend nodig, anders worden ze zuur... Je wilt geen zure rattenspies proeven.",
  o1 = "Ratten gevangen",
  g = { {"schurk", "scoundrel, scallywag"}, {"achterdek", "poop deck, rear deck"}, {"rattenvangersfluit", "rat catcher's flute"}, {"melodie", "melody, tune"}, {"ongedierte", "vermin"}, {"rotbeesten", "little buggers (rotbeest)"}, {"levend", "alive"}, {"dekzwabber", "swabby, deck swabber"}, {"schoppend", "kicking (schoppen)"}, {"zuur", "sour"}, {"rattenspies", "rat kabob"}, {"proeven", "to taste"} },
},

[6662] = { en = "Me Brother, Nipsy", tier = 1,
  t = "Mijn broer, Nipsy",
  d = "Mijn broer, Nipsy, heeft een zaak in rattenspiesjes aan de andere kant van de Deeprun. Breng deze krat ratten naar hem voordat ze bederven. Schiet op!$B$BJe hebt toch al eens met een tram gereden? Het is makkelijk. Stap gewoon in als ze aankomt, en geniet van de rit. En hou je armen en benen binnen tijdens de rit. Anders heb je de rest van je leven een houten been.",
  o = "Breng de Carton of Mystery Meat naar Nipsy in het Stormwind Deeprun Tram Depot.",
  p = "<Nipsy steekt zijn wijsvinger door een van de luchtgaten in de doos.>$b$bLevend en schoppend... en net op tijd!",
  c = "Arme Monty. Sinds het incident in Gnomeregan is hij niet meer de oude. Die jongen heeft nog nooit een oceaan gezien, laat staan dat hij een soort piraat is.$b$b<Nipsy zucht.>$b$bMaar hij zorgt er wel voor dat de trillende beestjes blijven komen.",
  g = { {"rattenspiesjes", "rat kabobs (rattenspiesje)"}, {"krat", "crate"}, {"bederven", "to go bad, spoil"}, {"rit", "ride"}, {"houten been", "wooden leg, peg leg"}, {"wijsvinger", "index finger"}, {"luchtgaten", "air holes (luchtgat)"}, {"niet meer de oude", "not the same any more"}, {"laat staan", "let alone"}, {"piraat", "pirate"}, {"zucht", "sighs (zuchten)"}, {"trillende", "twitching (trillen)"}, {"beestjes", "critters (beestje)"} },
},

[389] = { en = "Bazil Thredd", tier = 2,
  t = "Bazil Thredd",
  d = "VanCleef en ik waren lid van de Stonemasons Guild. Ons belangrijkste project was het herbouwen van Stormwind na de Oorlog.$B$BToen we klaar waren met ons werk, werden we bedrogen. De edelen weigerden ons te betalen voor ons werk. Een paar van de oudere Stonemasons kregen een baan bij de overheid aangeboden. Maar VanCleef weigerde dat, uit trouw aan alle Stonemasons. Hij leidde een opstand en verliet de stad. Hij zwoer wraak.$b$bZijn luitenant, Bazil Thredd, weet misschien meer over de plannen van VanCleef. Hij zit gevangen in de Stockade.",
  o = "Spreek met Warden Thelwater in de Stockade.",
  c = "Wat wil je in hemelsnaam? Zie je niet dat we hier een crisis hebben?$b$bBazil Thredd?! Waarom wil je met die schoft praten? Hoe weet ik dat je niet een van zijn handlangers bent, die hier komt helpen met zijn verdomde opstand? Als al die vervloekte cellen niet open stonden, gooide ik je misschien een tijdje in een cel!",
  g = { {"herbouwen", "rebuilding, to rebuild"}, {"bedrogen", "cheated (bedriegen)"}, {"edelen", "nobles (edele)"}, {"weigerden", "refused (weigeren)"}, {"overheid", "government"}, {"aangeboden", "offered (aanbieden)"}, {"trouw", "loyalty"}, {"opstand", "riot, uprising"}, {"zwoer", "swore (zweren)"}, {"luitenant", "lieutenant"}, {"in hemelsnaam", "in heaven's name"}, {"schoft", "bastard, scoundrel"}, {"handlangers", "cronies (handlanger)"}, {"cellen", "cells (cel)"} },
},

[971] = { en = "Knowledge in the Deeps", tier = 2,
  t = "Kennis in de diepte",
  d = "Zoals je misschien weet, verzamel ik kennis. Oude kennis. Machtige kennis. Kennis die deuren opent, en kennis die Zij Die Slapen kan wekken.$B$BEr gaan geruchten over een oud stuk kennis, het Lorgalis Manuscript, op de bodem van Blackfathom Deeps in Ashenvale. Daar woonden vroeger elfen die al lang dood zijn. Elfen die veel kennis hadden, voordat hun stad een ruïne werd.$B$BZoek in Blackfathom Deeps naar het manuscript. Doe dit, en ik zal het niet vergeten. Zelfs niet na... de laatste dagen.",
  o = "Breng het Lorgalis Manuscript naar Gerrig Bonegrip in de Forlorn Cavern in Ironforge.",
  p = "De reis naar Ashenvale is lang, en je taak is niet makkelijk. Maar als je het manuscript voor me haalt, $N... dan wordt je beloning groot.",
  c = "Je hebt het manuscript gevonden! Wat een blije dag is dit! Er worden kopieën gemaakt en verspreid, en de oude kennis van Lorgalis wordt eindelijk bekend bij mijn broeders en zusters!$B$BJe dienst aan ons is meer waard dan je weet, $N. Maar ik hoop dat dit geschenk je de dankbaarheid laat zien die wij aan onze bondgenoten geven.",
  g = { {"kennis", "knowledge, lore"}, {"machtige", "powerful (machtig)"}, {"wekken", "to awaken"}, {"geruchten", "rumours (gerucht)"}, {"bodem", "bottom"}, {"ruïne", "ruin"}, {"beloning", "reward"}, {"kopieën", "copies (kopie)"}, {"verspreid", "distributed (verspreiden)"}, {"geschenk", "gift"}, {"dankbaarheid", "gratitude"}, {"bondgenoten", "allies (bondgenoot)"} },
},

[1198] = { en = "In Search of Thaelrid", tier = 2,
  t = "Op zoek naar Thaelrid",
  d = "Er gaan tegenwoordig veel geruchten over het verbond tussen de Twilight's Hammer en de naga in Blackfathom Deeps, aan de kust van Ashenvale.$b$bMijn taak hier bij de Argent Dawn is om zoveel mogelijk informatie te verzamelen. Dan weten we wanneer en waar hulp nodig is.$b$bHet is nu al weken geleden dat ik een verkenner stuurde om te kijken wat er gebeurt in Blackfathom Deeps. Argent Guard Thaelrid heeft nog niets van zich laten horen.$b$bMijn andere verkenners zijn bezig met dringende zaken.$b$bZoek Thaelrid op en help hem voor mij, $n.",
  o = "Zoek Argent Guard Thaelrid op in Blackfathom Deeps.",
  c = "Het is goed dat Dawnwatcher Shaedlass je heeft gestuurd. Op deze verdorven plek is inderdaad een kwaadaardig plan aan de gang.",
  g = { {"tegenwoordig", "these days"}, {"verbond", "union, alliance"}, {"verkenner", "scout"}, {"niets van zich laten horen", "not reported back"}, {"verkenners", "scouts (verkenner)"}, {"dringende", "pressing, urgent (dringend)"}, {"zaken", "matters (zaak)"}, {"verdorven", "corrupted"}, {"inderdaad", "indeed"}, {"aan de gang", "underway"} },
},

[1275] = { en = "Researching the Corruption", tier = 2,
  t = "Onderzoek naar het verderf",
  d = "Dwaze bloedelfen spelen met demonische magie. Hebben ze niet gezien wat er gebeurde met de naga en met de saters van Kalimdor?$b$bIk ben bang dat de bloedelfen net zo misvormd zullen raken. Azeroth kan het zich niet veroorloven dat er weer een smerig ras van monsters geboren wordt.$b$bIk wil de hersenstammen van de saters en de naga bestuderen. Zo kan ik misschien afleiden welk lot de elfen te wachten staat. In Blackfathom Deeps, aan de kust van Ashenvale, vind je zowel saters als naga.$b$bHet is een lange reis, $n.",
  o = "Gershala Nightwhisper in Auberdine wil 8 Corrupt Brain stems hebben.",
  p = "Als ik genoeg stukken heb om te bestuderen, kan mijn echte werk beginnen. Met de verdorven hersenstammen van de saters en de naga van Blackfathom Deeps kan ik proberen een verband te vinden tussen de mutaties.$B$BMet die kennis kunnen we misschien voorkomen dat de bloedelfen nog dieper wegzakken in misvorming en kwaad.",
  c = "Je hebt ver gereisd en ongetwijfeld groot gevaar getrotseerd.$B$BJe hebt niet aan jezelf gedacht. Het is voor het welzijn van heel Azeroth dat je me helpt met mijn onderzoek. Ik dank je, $N, voor alles wat je hebt gedaan.$B$BEn nu moet je me excuseren. Ik heb nog veel werk te doen....",
  g = { {"dwaze", "foolish (dwaas)"}, {"bloedelfen", "blood elves (bloedelf)"}, {"demonische", "demonic (demonisch)"}, {"saters", "satyrs (sater)"}, {"misvormd", "deformed"}, {"het zich niet veroorloven", "cannot afford it (zich veroorloven)"}, {"smerig", "vile, filthy"}, {"hersenstammen", "brain stems (hersenstam)"}, {"afleiden", "to deduce"}, {"lot", "fate"}, {"verband", "connection, correlation"}, {"mutaties", "mutations (mutatie)"}, {"misvorming", "deformity"}, {"ongetwijfeld", "undoubtedly"}, {"welzijn", "good, well-being"} },
},

[3765] = { en = "The Corruption Abroad", tier = 2,
  t = "Het verderf in verre landen",
  d = "Stormwind... wat een drukke, levendige stad.$b$bIk ben van ver gekomen om hulp te zoeken. Je hoort vaak dat dappere avonturiers door de straten van deze stad trekken.$b$bMijn broer, Gershala, heeft hulp nodig in Darkshore. Hij woont in Auberdine, een stadje aan zee.$b$bDe reis is lang en groots. Daarom vraag ik om de hulp van een ervaren $c zoals jij.",
  o = "Reis naar Gershala Nightwhisper in Auberdine.",
  c = "Ah, dus mijn broer, Argos, heeft je gestuurd? Ik begrijp dat je moe moet zijn van je reis. Maar we hebben veel te bespreken.",
  g = { {"verderf", "corruption, ruin"}, {"levendige", "lively, bustling (levendig)"}, {"avonturiers", "adventurers (avonturier)"}, {"trekken", "roam, travel"}, {"groots", "epic, grand"}, {"ervaren", "experienced, seasoned"}, {"bespreken", "to discuss"} },
},

[386] = { en = "What Comes Around...", tier = 2,
  t = "Wat je zaait...",
  d = "Targorr the Dread diende onder Gath'Ilzogg als opperbeul. Zijn methodes waren meedogenloos, zelfs voor smerige orcs. Mannen die dapper vochten om het koninkrijk te verdedigen, werden gemarteld als hij daar zin in had. Nu zit hij gevangen in de Stormwind Stockade, veroordeeld tot de dood. Maar er klopt iets niet. Een van de bureaucratische edelen heeft zijn executie uitgesteld. Ik weet zeker dat er iets niet in de haak is.$b$bMaak een einde aan Targorr the Dread, $N. Reis naar The Stockade en onthoofd hem voordat we bedrogen worden.",
  o = "Breng het hoofd van Targorr the Dread naar Guard Berton in Lakeshire.",
  p = "Ben je al in Stormwind geweest, in The Stockade? Ik ben bang dat het bedrog dat Targorr the Dread zo lang in leven heeft gehouden, hem uiteindelijk zijn vrijheid zal geven. Hij is veroordeeld tot de dood, $N. Niet om een politieke pion te zijn voor de grillen van een edelman.",
  c = "Targorr the Dread heeft eindelijk zijn lot gevonden. Ik ben in elk geval blij dat het beest nu weet hoe het voelt om zelf in de meedogenloze greep van de Dood te zitten. Je hebt het goed gedaan, $N. Soms vind je de echtste gerechtigheid alleen buiten de rechtszaal, ver weg van de troebele blik van de politiek.",
  g = { {"zaait", "sow (zaaien)"}, {"opperbeul", "supreme executioner"}, {"meedogenloos", "ruthless"}, {"gemarteld", "tortured (martelen)"}, {"veroordeeld", "sentenced (veroordelen)"}, {"bureaucratische", "bureaucratic (bureaucratisch)"}, {"executie", "execution"}, {"uitgesteld", "put on hold, delayed (uitstellen)"}, {"niet in de haak", "not right, foul play"}, {"onthoofd", "behead (onthoofden)"}, {"bedrog", "trickery, deceit"}, {"pion", "pawn"}, {"grillen", "whims (gril)"}, {"greep", "grip"}, {"rechtszaal", "courtroom"}, {"troebele", "clouded (troebel)"} },
},

[1199] = { en = "Twilight Falls", tier = 2,
  t = "De val van de Twilight",
  d = "De leden van de Twilight's Hammer krijgen kracht uit de oude rituelen van de chaotische Oude Goden. Ze willen hun duistere meesters laten terugkeren, en dood en angst over de wereld verspreiden.$b$bWij denken dat de Twilight's Hammer een verbond heeft gesloten met de naga. Ze verzamelen zich in Blackfathom Deeps, aan de kust van Ashenvale.$b$bWelk kwaadaardig plan er ook broeit in de diepten van de oude tempel, het moet verijdeld worden.$b$bVoer oorlog tegen de Hammer en breng bewijs van je daden mee terug. Je moeite wordt rijk beloond.",
  o = "Breng 10 Twilight Pendants naar Argent Guard Manados in Darnassus.",
  p = "Blackfathom Deeps was ooit een oude tempel van de nachtelfen. Er stond vroeger een heel machtige maanbron. Wie weet welk kwaad daar nu broeit door de Twilight's Hammer.$B$BIs het je al een beetje gelukt om ze te verdrijven?",
  c = "Jij bent ongetwijfeld van dapper en edel bloed, $N. De Argent Dawn prijst je voor je strijd tegen het kwaad.",
  g = { {"leden", "members (lid)"}, {"rituelen", "rites, rituals (ritueel)"}, {"chaotische", "chaotic (chaotisch)"}, {"terugkeren", "to return"}, {"gesloten", "made, closed (een verbond sluiten: to ally)"}, {"broeit", "brews (broeien)"}, {"diepten", "depths (diepte)"}, {"verijdeld", "thwarted (verijdelen)"}, {"voer oorlog", "wage war (oorlog voeren)"}, {"rijk beloond", "handsomely rewarded"}, {"maanbron", "moonwell"}, {"edel", "noble"}, {"prijst", "praises, commends (prijzen)"} },
},

[377] = { en = "Crime and Punishment", tier = 2,
  t = "Misdaad en straf",
  d = "Alsof de verwaarlozing van de inwoners van Duskwood nog niet erg genoeg was. Nu spuugt het House of Nobles de Darkshire Council in het gezicht. Ze hebben besloten Dextren Ward in Stormwind op te sluiten, in plaats van de schurk te onthoofden zoals Lord Ebonlocke had bepaald.$b$bWard werd betrapt toen hij lijken van het kerkhof verkocht aan Morbent Fel. Op die misdaad staat de doodstraf. Toch zegt Stormwind dat Ward hun gevangene is.$b$bVermoord Ward in The Stormwind Stockade, breng me zijn hand, en ik zal je belonen.",
  o = "Councilman Millstipe uit Darkshire wil dat je hem de hand van Dextren Ward brengt.",
  p = "Zolang een lijkenschender zoals Dextren Ward mag blijven leven, is de gerechtigheid verraden. Kom terug als het doodvonnis van Lord Ebonlocke is uitgevoerd op die schender, Ward. Dan geven we de families van de doden de rust die ze verdienen. En nog beter: we sturen een duidelijke boodschap naar het House of Nobles in Stormwind.",
  c = "Dus Dextren Ward heeft eindelijk betaald voor zijn misdaden tegen de mensheid? Opgeruimd staat netjes, zeg ik. En proost op jou, mijn vriend! Je hebt de families van de doden niet alleen de gemoedsrust gegeven die ze verdienen. Je hebt ook een scherpe boodschap gestuurd naar die corrupte bureaucraten in het House of Nobles. Stormwind moet zorgen voor wat de mensen van Duskwood nodig hebben, of we maken ons los van hun tirannie.",
  g = { {"verwaarlozing", "neglect"}, {"inwoners", "residents (inwoner)"}, {"spuugt", "spits (spugen)"}, {"op te sluiten", "to imprison, lock up (opsluiten)"}, {"betrapt", "caught (betrappen)"}, {"kerkhof", "cemetery"}, {"doodstraf", "death penalty"}, {"vermoord", "assassinate, murder (vermoorden)"}, {"lijkenschender", "molester of the dead"}, {"verraden", "betrayed (verraden)"}, {"doodvonnis", "death sentence"}, {"schender", "defiler"}, {"boodschap", "message"}, {"opgeruimd staat netjes", "good riddance"}, {"bureaucraten", "bureaucrats (bureaucraat)"}, {"tirannie", "tyranny"} },
},

[387] = { en = "Quell The Uprising", tier = 2,
  t = "Sla de opstand neer",
  d = "De opstand moet neergeslagen worden! Ik heb je hulp nodig. Als bekend wordt dat de gevangenis onder de voet is gelopen, verlies ik mijn baan! Dit is vals spel, als ik het ooit heb gezien. Maar nu is het belangrijk dat we deze gevangenen dwingen zich over te geven, voor de veiligheid van Stormwind.$b$bDe straf voor opstand is de dood. Dood een paar van die ontaarde types! Dan krijgen we de zaak wel weer onder controle.",
  o = "Warden Thelwater uit Stormwind wil dat je 10 Defias Prisoners, 8 Defias Convicts en 8 Defias Insurgents doodt in The Stockade.",
  p = "The Stockade is nog steeds onder de voet gelopen! Die ratten van de Defias moeten zien dat we hun gedrag niet tolereren. Ga nu terug naar beneden en laat je kracht zien!",
  c = "Je hebt dapper gevochten in The Stockade, $N. Het is duidelijk dat dit probleem groter is dan wij tweeën. Maar je hebt het goed gedaan, en daarvoor ben ik je dankbaar.",
  g = { {"sla", "put (neerslaan: quell)"}, {"neergeslagen", "quelled (neerslaan)"}, {"gevangenis", "prison"}, {"onder de voet is gelopen", "is overrun (onder de voet lopen)"}, {"vals spel", "foul play"}, {"dwingen", "to force"}, {"zich over te geven", "to surrender (zich overgeven)"}, {"veiligheid", "safety"}, {"ontaarde", "deviant (ontaard)"}, {"onder controle", "under control"}, {"gedrag", "behaviour, actions"}, {"tolereren", "to tolerate"} },
},

[388] = { en = "The Color of Blood", tier = 2,
  t = "De kleur van bloed",
  d = "Bitterheid stroomt door mijn aderen als een koude rivier. Mijn kleinzoon, Mac, was zo'n goede jongen. Pas 14 jaar oud. Toen het leger naar het front werd gestuurd, pakte Mac de wapens op om de stad te verdedigen. Hij was bewaker in The Stockade, waar de bende van de Defias opgesloten zit. Mac gaf een paar gevangenen een standje, omdat ze hun wollen dekens scheurden om er sjaals van te maken, een symbool van hun bende. Daarvoor werd Mac in zijn rug gestoken.$b$bIk wil wraak. Breng me 10 van hun kostbare wollen bandana's. Ze hebben de kleur van bloed.",
  o = "Nikova Raskol uit Stormwind wil dat je 10 Red Wool Bandanas verzamelt.",
  p = "Ik zie dat je terug bent, $C. Heb je al 10 Red Wool Bandanas verzameld van dat tuig van de Defias in The Stockade?",
  c = "Dus voor deze bandana's, smerige tekens van verderf, moest mijn Mac sterven? Wat een verspilling. Wat een tragisch offer.$b$bMaar helaas kan ik niet terug naar het verleden. Weet wel, $N, dat je met je daden gerechtigheid hebt gebracht voor mijn familie.",
  g = { {"bitterheid", "bitterness"}, {"aderen", "veins (ader)"}, {"kleinzoon", "grandson"}, {"leger", "army"}, {"bewaker", "guard"}, {"bende", "gang"}, {"een standje", "a telling-off (een standje geven: to reprimand)"}, {"wollen", "woollen"}, {"dekens", "blankets (deken)"}, {"scheurden", "tore (scheuren)"}, {"sjaals", "scarves (sjaal)"}, {"gestoken", "stabbed (steken)"}, {"tekens", "tokens, signs (teken)"}, {"verspilling", "waste"}, {"offer", "sacrifice"}, {"helaas", "alas, unfortunately"} },
},

[378] = { en = "The Fury Runs Deep", tier = 2,
  t = "De woede zit diep",
  d = "Je hebt je trouw aan King Magni bewezen, $c. En je haat tegen het tuig van de Dark Irons is net zo groot als de mijne.$b$bEr is een taak die ik zelf wil afmaken, maar mijn eer verplicht me om bij Longbraid te blijven. Maar Roggo heeft informatie verzameld die bewijst dat Kam Deepfury een van de samenzweerders achter de aanval op de Thandol Span was. Door de plannen van Deepfury heeft Longbraid familie verloren.$b$bDeepfury wordt om politieke redenen vastgehouden in de Stormwind Stockade. Ik wil hem dood hebben, $N. Voor Longbraid! Breng me zijn hoofd!",
  o = "Motley Garmason wil dat je hem het hoofd van Kam Deepfury brengt in Dun Modr.",
  p = "Ik laat dwaze menselijke bureaucratie niet tussen dwergenzaken komen, $N. Het is bewezen dat Kam Deepfury een van de samenzweerders achter de aanval op de Thandol Span was. Goede mensen van King Magni hebben hun leven verloren door het bedrog van Deepfury. De mensen vinden het misschien goed om Deepfury te laten wegrotten in The Stockade, maar ik slaap pas weer rustig als Deepfury dood is.",
  c = "Dus Kam Deepfury heeft eindelijk gevoeld hoe het is om zelf de Dood te ontmoeten? Goed. Net goed voor dat laffe tuig van de Dark Irons. Je hebt het goed gedaan, $C. De slachtoffers van de aanval op de Thandol Span waren gewoon slachtoffers in een wereld vol oorlog en onrust. Hun families hebben nu de rust om te weten dat Deepfury de straf heeft gekregen die hij verdiende. De dood van de broer van Longbraid is gewroken.",
  g = { {"woede", "fury, anger"}, {"haat", "hatred"}, {"verplicht", "binds, obliges (verplichten)"}, {"samenzweerders", "conspirators (samenzweerder)"}, {"vastgehouden", "held (vasthouden)"}, {"bureaucratie", "bureaucracy"}, {"dwergenzaken", "dwarven matters"}, {"wegrotten", "to rot away"}, {"net goed voor", "serves right"}, {"slachtoffers", "victims (slachtoffer)"}, {"onrust", "unrest"}, {"gewroken", "avenged (wreken)"} },
},

[1200] = { en = "Blackfathom Villainy", tier = 2,
  t = "Schurkerij in Blackfathom",
  d = "Mijn kracht is weg. Ik heb je hulp nodig!$b$bLang geleden was deze plek een grote tempel van Elune. Maar door een ongeluk werd het een ruïne. Het verderf van een Oude God sijpelde omhoog van onder de aarde en besmette de heilige Moon Well.$b$bAku'Mai, een dienaar van de Oude God, kwam op uit het water.$b$bDe sekteleden van de Twilight's Hammer hebben een verbond gesloten met de naga om deze plek te bezetten. De sekteleden worden geleid door Kelris. Ze offeren onschuldigen aan Aku'Mai om macht te krijgen.$b$bDood Kelris en breng zijn hoofd naar Selgorm in Darnassus, $N, alsjeblieft.",
  o = "Breng het hoofd van Twilight Lord Kelris naar Dawnwatcher Selgorm in Darnassus.",
  p = "Tijd is kostbaar, $C.$B$BMijn taak hier in Darnassus is ervoor zorgen dat de Argent Dawn bloeit, en dat de kwade krachten die Kalimdor binnendringen worden tegengehouden.$B$BZeg snel wat je wilt, of ga verder.",
  c = "Kelris is ons al een hele tijd ontlopen.$B$BHet lijkt erop dat Kelris een rol speelde, telkens als het kwaad zich in deze streek liet zien. Een tijdlang dachten we dat hij dood of verdwenen was.$B$BMaar dit is heel logisch. Door een einde te maken aan zijn heerschappij heb je de levens van veel onschuldige mensen gespaard.$B$BBij het Licht! Iemand offeren aan een dienaar van een Oude God voor je eigen voordeel is meer dan verwerpelijk!$B$BJe hebt een grote daad verricht, $N. Ik salueer voor je namens de Argent Dawn.",
  g = { {"schurkerij", "villainy"}, {"ongeluk", "misfortune, accident"}, {"sijpelde", "seeped (sijpelen)"}, {"besmette", "tainted (besmetten)"}, {"heilige", "sacred, holy (heilig)"}, {"sekteleden", "cultists (sektelid)"}, {"bezetten", "to occupy"}, {"offeren", "to sacrifice"}, {"bloeit", "thrives (bloeien)"}, {"binnendringen", "encroach, invade"}, {"tegengehouden", "stopped, thwarted (tegenhouden)"}, {"heerschappij", "reign"}, {"gespaard", "spared (sparen)"}, {"voordeel", "gain, advantage"}, {"verwerpelijk", "reprehensible"}, {"verricht", "performed, done (verrichten)"} },
